// ===== GEMINI DENTRO DE GOOGLE SHEETS =====
// Menú Extensiones > Apps Script. Borra lo que haya y pega esto entero.
// Guarda con el icono del disquete. Vuelve a la hoja.
// En una celda escribe:   =GEMINI("resume en 10 palabras"; A2)
// (En España el separador suele ser ";". Si te da error, prueba con ",")

const CLAVE  = "PEGA_AQUI_TU_CLAVE_QUE_EMPIEZA_POR_AIza";
const MODELO = "gemini-2.5-flash";   // el rápido y barato

/**
 * Pregunta a Gemini sobre el contenido de una celda.
 * @param {string} instruccion Lo que quieres que haga.
 * @param {string} texto La celda de la que parte.
 * @return {string} La respuesta de Gemini.
 * @customfunction
 */
function GEMINI(instruccion, texto) {
  if (!instruccion) return "Falta la instruccion";

  const contenido = instruccion + "\n\nTEXTO:\n" + (texto || "");
  const url = "https://generativelanguage.googleapis.com/v1beta/models/"
            + MODELO + ":generateContent";

  const opciones = {
    method: "post",
    contentType: "application/json",
    headers: { "x-goog-api-key": CLAVE },
    muteHttpExceptions: true,
    payload: JSON.stringify({
      contents: [{ parts: [{ text: contenido }] }],
      generationConfig: { temperature: 0.2, maxOutputTokens: 800 }
    })
  };

  const respuesta = UrlFetchApp.fetch(url, opciones);
  const codigo    = respuesta.getResponseCode();
  const cuerpo    = JSON.parse(respuesta.getContentText());

  if (codigo !== 200) {
    return "ERROR " + codigo + ": " +
      (cuerpo.error && cuerpo.error.message ? cuerpo.error.message : "sin detalle");
  }
  if (!cuerpo.candidates || !cuerpo.candidates.length) {
    return "Sin respuesta (posible bloqueo por seguridad)";
  }
  return cuerpo.candidates[0].content.parts[0].text.trim();
}
